import{_ as t,a as e,b as i,c as a,d as n,e as r}from"./chunks/9.BXFUmzx_.js";import{_ as s,b as l,a as h}from"./chunks/6.C90syIqY.js";import{_ as u,o as p,c,a0 as d}from"./chunks/framework.DRjqbEpm.js";const _=JSON.parse('{"title":"🚀 Quick Start: Installation & First Setup","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/installation.md","filePath":"en/guide/installation.md"}'),m={name:"en/guide/installation.md"};function g(b,o,f,q,w,k){return p(),c("div",null,[...o[0]||(o[0]=[d('<h1 id="🚀-quick-start-installation-first-setup" tabindex="-1">🚀 Quick Start: Installation &amp; First Setup <a class="header-anchor" href="#🚀-quick-start-installation-first-setup" aria-label="Permalink to &quot;🚀 Quick Start: Installation &amp; First Setup&quot;">​</a></h1><p>Welcome to V-Train! This guide will help you set up the extension in just a few minutes. Soon, you will see progress bars on your favorite video sites.</p><div class="info custom-block"><p class="custom-block-title">💡 What is V-Train?</p><p>V-Train is a Chrome extension. It automatically shows a <strong>red progress bar</strong> under video thumbnails. This helps you track what you have watched, just like YouTube! It runs 100% locally and does not upload your data.</p></div><hr><h2 id="_1-how-to-install" tabindex="-1">1. How to Install <a class="header-anchor" href="#_1-how-to-install" aria-label="Permalink to &quot;1. How to Install&quot;">​</a></h2><h3 id="✅-method-a-install-from-chrome-web-store-recommended" tabindex="-1">✅ Method A: Install from Chrome Web Store (Recommended) <a class="header-anchor" href="#✅-method-a-install-from-chrome-web-store-recommended" aria-label="Permalink to &quot;✅ Method A: Install from Chrome Web Store (Recommended)&quot;">​</a></h3><p>This is the easiest and safest way for most users.</p><ol><li><p>Click the link below to open the Chrome Web Store:</p><p><strong><a href="https://chromewebstore.google.com/detail/v-train-adaptive-video-ba/cikabjkegiefjgalfncfoehmkpmkoiaf" target="_blank" rel="noreferrer">👉 Install V-Train</a></strong></p></li><li><p>Click the blue &quot;<strong>Add to Chrome</strong>&quot; button in the top right corner.</p><blockquote><p><img src="'+t+'" alt="Chrome Web Store Installation Page"></p></blockquote></li><li><p>A confirmation window will appear. Click &quot;<strong>Add extension</strong>&quot;.</p></li><li><p>After it finishes, the V-Train icon (a dark VT logo) will appear in the top right corner of Chrome.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">🎉 Check if Installation is Successful</p><p>If you see the VT icon in the top right, the installation was successful! If you do not see it, please read the &quot;Pin the Extension&quot; step below.</p></div><hr><h3 id="🔧-method-b-manual-installation-developer-mode" tabindex="-1">🔧 Method B: Manual Installation (Developer Mode) <a class="header-anchor" href="#🔧-method-b-manual-installation-developer-mode" aria-label="Permalink to &quot;🔧 Method B: Manual Installation (Developer Mode)&quot;">​</a></h3><p>If you downloaded the source code from GitHub, you can load it manually using Developer Mode.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Note</p><p>This method is for advanced users. Please be careful with extensions from unknown sources.</p></div><ol><li><p>Download and extract the V-Train source code to a folder on your computer.</p></li><li><p>Type <code>chrome://extensions</code> in the Chrome address bar and press Enter.</p></li><li><p>Turn on the <strong>&quot;Developer mode&quot;</strong> switch in the top right corner.</p><blockquote><p><img src="'+e+'" alt="Enable Developer Mode"></p></blockquote></li><li><p>Click the <strong>&quot;Load unpacked&quot;</strong> button in the top left.</p></li><li><p>Select the V-Train folder you just extracted (it must contain the <code>manifest.json</code> file).</p></li><li><p>Click &quot;Select Folder&quot;. V-Train will now appear in your list of extensions!</p></li></ol><div class="info custom-block"><p class="custom-block-title">📌 Developer Mode Tip</p><p>If you install via Developer Mode, Chrome might show a &quot;Disable developer mode extensions&quot; popup when you restart the browser. Just click &quot;Cancel&quot; to keep using V-Train.</p></div><hr><h2 id="_2-pin-the-extension" tabindex="-1">2. Pin the Extension <a class="header-anchor" href="#_2-pin-the-extension" aria-label="Permalink to &quot;2. Pin the Extension&quot;">​</a></h2><p>Chrome hides new extensions by default. You should &quot;pin&quot; V-Train so you can easily access it.</p><ol><li><p>Click the <strong>puzzle piece icon 🧩</strong> (Extensions button) in the top right corner of Chrome.</p><blockquote><p><img src="'+i+'" alt="Click Puzzle Icon"></p></blockquote></li><li><p>Find <strong>V-Train Adaptive Video</strong> in the list.</p></li><li><p>Click the <strong>pushpin icon 📌</strong> next to it. It will turn blue.</p><blockquote><p><img src="'+a+'" alt="Pin V-Train Icon"></p></blockquote></li><li><p>Done! The VT icon will now stay on your toolbar.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">Quick Tip</p><p>If you use Microsoft Edge, the steps are the same. Just look for the puzzle piece icon on your toolbar!</p></div><hr><h2 id="_3-first-launch-open-the-dashboard" tabindex="-1">3. First Launch: Open the Dashboard <a class="header-anchor" href="#_3-first-launch-open-the-dashboard" aria-label="Permalink to &quot;3. First Launch: Open the Dashboard&quot;">​</a></h2><p>After pinning, you are ready to use V-Train!</p><ol><li><p><strong>Click the VT icon on the toolbar</strong>.</p></li><li><p>The dark-themed <strong>Dashboard</strong> will open.</p><blockquote><p><img src="'+s+'" alt="V-Train Dashboard Main Screen"></p></blockquote></li></ol><p>This Dashboard is the &quot;Command Center&quot;. You can control all settings from here.</p><hr><h2 id="_4-authorize-site-the-most-important-step" tabindex="-1">4. Authorize Site: The Most Important Step <a class="header-anchor" href="#_4-authorize-site-the-most-important-step" aria-label="Permalink to &quot;4. Authorize Site: The Most Important Step&quot;">​</a></h2><p>V-Train requires your permission to work on a website. This protects your privacy. V-Train will not run on any website unless you explicitly allow it.</p><p>You must do this <strong>once for each website</strong> where you want to use V-Train.</p><h3 id="steps" tabindex="-1">Steps: <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps:&quot;">​</a></h3><ol><li><p>Open the video website you want to track (for example, the homepage or video list page).</p></li><li><p>Click the VT icon on the toolbar to <strong>open the V-Train Dashboard</strong>.</p></li><li><p>Click the blue <strong>&quot;Authorize &amp; Enable Current Site&quot;</strong> button at the <strong>top</strong> of the panel.</p><blockquote><p><img src="'+l+'" alt="Authorize Button"></p></blockquote></li><li><p>Chrome will ask you to confirm: &quot;Allow this extension to read and change data on this site?&quot;. Click <strong>&quot;Allow&quot;</strong>.</p></li><li><p>The button will turn <strong>green</strong> and say &quot;✅ Site Authorized&quot;.</p><blockquote><p><img src="'+n+'" alt="Authorization Success Status"></p></blockquote></li><li><p>If V-Train already supports this website, <strong>refresh the page</strong>. You will see <strong>red progress bars</strong> under the video thumbnails!</p></li></ol><div class="warning custom-block"><p class="custom-block-title">⚠️ Still no progress bars? Do not worry!</p><p>If you see &quot;Site Authorized&quot; but still do not see progress bars, this is normal. It means V-Train does not know how to read this website yet. You must use the &quot;Adaptive Engine&quot; to train it. Please read the <a href="./adaptive-engine.html">Adaptive Engine Training Guide</a>.</p></div><hr><h2 id="_5-about-the-default-monitoring-off-mode" tabindex="-1">5. About the Default &quot;Monitoring Off&quot; Mode <a class="header-anchor" href="#_5-about-the-default-monitoring-off-mode" aria-label="Permalink to &quot;5. About the Default &quot;Monitoring Off&quot; Mode&quot;">​</a></h2><p>After you install V-Train and authorize a website, you might still not see progress bars.</p><p>This is because V-Train is set to <strong>&quot;Monitoring Off&quot; mode by default after installation</strong>.</p><h3 id="what-is-monitoring-off-mode" tabindex="-1">What is Monitoring Off Mode? <a class="header-anchor" href="#what-is-monitoring-off-mode" aria-label="Permalink to &quot;What is Monitoring Off Mode?&quot;">​</a></h3><p>Sometimes you may want to watch a video without recording your progress. When &quot;Monitoring Off&quot; is active, V-Train acts as if it is turned off. It will not show progress bars, and it will not record what you watch.</p><p>We default to Monitoring Off so you can explore the Dashboard first before V-Train starts recording your activity.</p><h3 id="how-to-turn-on-monitoring-to-start-tracking" tabindex="-1">How to turn on &quot;Monitoring&quot; to start tracking <a class="header-anchor" href="#how-to-turn-on-monitoring-to-start-tracking" aria-label="Permalink to &quot;How to turn on &quot;Monitoring&quot; to start tracking&quot;">​</a></h3><ol><li><p>Open the V-Train Dashboard.</p></li><li><p>Look at the &quot;<strong>Status Toggle</strong>&quot; at the top. It currently shows a gray light for &quot;<strong>Monitoring Off</strong>&quot;.</p></li><li><p><strong>Click this toggle</strong> to turn it green. It will say &quot;<strong>🟢 Monitoring</strong>&quot;.</p><blockquote><p><img src="'+h+'" alt="Monitoring Toggle"></p></blockquote></li><li><p>When the toggle is green, V-Train is active! <strong>Refresh the page</strong>, and the progress bars will appear.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">💡 Want to pause anytime?</p><p>You can switch modes anytime! If you do not want V-Train to record, turn the switch to &quot;Monitoring Off&quot;. When you want to record again, switch back to &quot;Monitoring&quot;.</p></div><hr><h2 id="_6-incognito-mode-setup" tabindex="-1">6. Incognito Mode Setup <a class="header-anchor" href="#_6-incognito-mode-setup" aria-label="Permalink to &quot;6. Incognito Mode Setup&quot;">​</a></h2><p>V-Train supports incognito mode, but you must enable it manually.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Disabled by default</p><p>For security, Chrome does not allow extensions to run in incognito mode by default. You must grant permission manually.</p></div><h3 id="how-to-allow-v-train-in-incognito-mode" tabindex="-1">How to allow V-Train in Incognito mode <a class="header-anchor" href="#how-to-allow-v-train-in-incognito-mode" aria-label="Permalink to &quot;How to allow V-Train in Incognito mode&quot;">​</a></h3><ol><li><p>Type <code>chrome://extensions</code> in the Chrome address bar and press Enter.</p></li><li><p>Find <strong>V-Train Adaptive Video</strong> and click &quot;<strong>Details</strong>&quot;.</p></li><li><p>Scroll down and find the &quot;<strong>Allow in Incognito</strong>&quot; option.</p></li><li><p>Turn on the switch.</p><blockquote><p><img src="'+r+'" alt="Allow Incognito Mode"></p></blockquote></li></ol><p>Now, V-Train will work normally in incognito windows!</p><div class="info custom-block"><p class="custom-block-title">📌 Privacy in Incognito Mode</p><p>Even if you enable V-Train in incognito mode, you can still switch to &quot;Monitoring Off&quot; from the Dashboard. This stops V-Train from recording your progress.</p></div><hr><h2 id="_7-common-installation-q-a" tabindex="-1">7. Common Installation Q&amp;A <a class="header-anchor" href="#_7-common-installation-q-a" aria-label="Permalink to &quot;7. Common Installation Q&amp;A&quot;">​</a></h2><h3 id="❓-q-i-cannot-find-the-v-train-icon-after-installing-what-should-i-do" tabindex="-1">❓ Q: I cannot find the V-Train icon after installing. What should I do? <a class="header-anchor" href="#❓-q-i-cannot-find-the-v-train-icon-after-installing-what-should-i-do" aria-label="Permalink to &quot;❓ Q: I cannot find the V-Train icon after installing. What should I do?&quot;">​</a></h3><p>Please read step &quot;2. Pin the Extension&quot; on this page. Click the puzzle piece icon on your Chrome toolbar and pin V-Train manually.</p><hr><h3 id="❓-q-why-didn-t-chrome-show-a-popup-when-i-clicked-authorize" tabindex="-1">❓ Q: Why didn&#39;t Chrome show a popup when I clicked authorize? <a class="header-anchor" href="#❓-q-why-didn-t-chrome-show-a-popup-when-i-clicked-authorize" aria-label="Permalink to &quot;❓ Q: Why didn&#39;t Chrome show a popup when I clicked authorize?&quot;">​</a></h3><p>You might be on a system page (like <code>chrome://...</code>) or a local file (like <code>file://...</code>). V-Train can only be authorized on normal websites starting with <code>http://</code> or <code>https://</code>. Please go to a video website first, then click authorize.</p><hr><h3 id="❓-q-i-authorized-the-site-but-there-are-still-no-progress-bars-why" tabindex="-1">❓ Q: I authorized the site, but there are still no progress bars. Why? <a class="header-anchor" href="#❓-q-i-authorized-the-site-but-there-are-still-no-progress-bars-why" aria-label="Permalink to &quot;❓ Q: I authorized the site, but there are still no progress bars. Why?&quot;">​</a></h3><p>Please check these steps:</p><ol><li>✅ Confirm the status toggle on the Dashboard says &quot;🟢 Monitoring&quot;, not &quot;Monitoring Off&quot;.</li><li>✅ Confirm the authorize button is green and says &quot;Site Authorized&quot;.</li><li>✅ Refresh the webpage.</li><li>If you checked all steps and still see no progress bars, V-Train probably does not support this site yet. You can use the <a href="./adaptive-engine.html">Adaptive Engine</a> to train it, or check the <a href="https://github.com/vtrain-labs/community-rules" target="_blank" rel="noreferrer">Community Rules Library</a> to see if someone else has already trained it.</li></ol><hr><h3 id="❓-q-the-dashboard-is-in-chinese-how-do-i-change-it-to-english" tabindex="-1">❓ Q: The Dashboard is in Chinese. How do I change it to English? <a class="header-anchor" href="#❓-q-the-dashboard-is-in-chinese-how-do-i-change-it-to-english" aria-label="Permalink to &quot;❓ Q: The Dashboard is in Chinese. How do I change it to English?&quot;">​</a></h3><p>There is a <strong>Language</strong> menu at the top right of the Dashboard. Click it and select &quot;English&quot;. The language will change immediately.</p><hr><h3 id="❓-q-can-i-use-this-extension-on-microsoft-edge" tabindex="-1">❓ Q: Can I use this extension on Microsoft Edge? <a class="header-anchor" href="#❓-q-can-i-use-this-extension-on-microsoft-edge" aria-label="Permalink to &quot;❓ Q: Can I use this extension on Microsoft Edge?&quot;">​</a></h3><p>Yes! Microsoft Edge supports Chrome extensions. You can install V-Train from the Chrome Web Store using Edge. The steps are exactly the same as in Chrome.</p><div class="danger custom-block"><p class="custom-block-title">🚫 Unsupported Browsers</p><p>V-Train only supports Chromium-based browsers (like Chrome, Edge, and Brave). Firefox and Safari are <strong>not supported</strong>.</p></div><hr><h2 id="_8-next-steps" tabindex="-1">8. Next Steps... <a class="header-anchor" href="#_8-next-steps" aria-label="Permalink to &quot;8. Next Steps...&quot;">​</a></h2><p>Congratulations on setting up V-Train! 🎉 To learn more about its features, please read:</p><ul><li><strong><a href="./dashboard.html">Dashboard Overview →</a></strong> — Learn what every button does.</li><li><strong><a href="./adaptive-engine.html">Adaptive Engine: Train New Sites →</a></strong> — Teach V-Train to support any video website.</li><li><strong><a href="./pro-features.html">Pro Features Guide →</a></strong> — Unlock infinite records and the Bookmark Vault.</li></ul>',72)])])}const x=u(m,[["render",g]]);export{_ as __pageData,x as default};
